// RegisterSandboxServiceHandler registers svc as the pethost.sandboxes.v1.SandboxService
// implementation on server.
func RegisterSandboxServiceHandler(server *connect.Server, svc SandboxServiceHandler) {
	adapter := sandboxServiceHandler{svc: svc}
	server.Register(
		connect.Method{Spec: sandboxServiceGetWorkspaceSpec(), Handler: adapter.getWorkspace},
		connect.Method{Spec: sandboxServiceSetSshKeysSpec(), Handler: adapter.setSshKeys},
		connect.Method{Spec: sandboxServiceSetSecretSpec(), Handler: adapter.setSecret},
		connect.Method{Spec: sandboxServiceDeleteSecretSpec(), Handler: adapter.deleteSecret},
		connect.Method{Spec: sandboxServiceCreateSandboxSpec(), Handler: adapter.createSandbox},
		connect.Method{Spec: sandboxServiceGetSandboxSpec(), Handler: adapter.getSandbox},
		connect.Method{Spec: sandboxServiceListSandboxesSpec(), Handler: adapter.listSandboxes},
		connect.Method{Spec: sandboxServiceUpdateSandboxSpec(), Handler: adapter.updateSandbox},
		connect.Method{Spec: sandboxServicePauseSandboxSpec(), Handler: adapter.pauseSandbox},
		connect.Method{Spec: sandboxServiceStopSandboxSpec(), Handler: adapter.stopSandbox},
		connect.Method{Spec: sandboxServiceResumeSandboxSpec(), Handler: adapter.resumeSandbox},
		connect.Method{Spec: sandboxServiceDeleteSandboxSpec(), Handler: adapter.deleteSandbox},
		connect.Method{Spec: sandboxServiceConnectSandboxSpec(), Handler: adapter.connectSandbox},
		connect.Method{Spec: sandboxServiceGetSandboxMetricsSpec(), Handler: adapter.getSandboxMetrics},
		connect.Method{Spec: sandboxServiceListSandboxEventsSpec(), Handler: adapter.listSandboxEvents},
		connect.Method{Spec: sandboxServiceWatchSandboxEventsSpec(), Handler: adapter.watchSandboxEvents},
		connect.Method{Spec: sandboxServiceCreateTemplateSpec(), Handler: adapter.createTemplate},
		connect.Method{Spec: sandboxServiceGetTemplateSpec(), Handler: adapter.getTemplate},
		connect.Method{Spec: sandboxServiceListTemplatesSpec(), Handler: adapter.listTemplates},
		connect.Method{Spec: sandboxServiceDeleteTemplateSpec(), Handler: adapter.deleteTemplate},
		connect.Method{Spec: sandboxServiceListUsageSpec(), Handler: adapter.listUsage},
	)
}

