// SandboxRuntimeServiceClient is a client for the pethost.sandboxes.v1.SandboxRuntimeService
// service.
type SandboxRuntimeServiceClient interface {
	// Runs a shell command and waits for it (wait_seconds): its exit and output, or RUNNING with
	// its output so far while it runs on. Only timeout_seconds or StopCommand ends it early.
	RunCommand(context.Context, *sandboxesv1.RunCommandRequest) (*sandboxesv1.Command, error)
	// A command, after waiting for it to end (wait_seconds). The last 100 that ended are kept.
	GetCommand(context.Context, *sandboxesv1.GetCommandRequest) (*sandboxesv1.Command, error)
	// SIGTERM, then SIGKILL 10 s later if it still runs. Answers once it has ended. A command that
	// has ended has what it left running killed at once: its background jobs, or a fork bomb.
	StopCommand(context.Context, *sandboxesv1.StopCommandRequest) (*sandboxesv1.Command, error)
	// The commands running now, started by the API, SSH or a terminal, without their
	// output.
	ListCommands(context.Context, *sandboxesv1.ListCommandsRequest) (*sandboxesv1.ListCommandsResponse, error)
	// A command's output from the last 64 KiB, then live, until it ends.
	WatchCommand(context.Context, *sandboxesv1.WatchCommandRequest) (SandboxRuntimeServiceWatchCommandClientStream, error)
	// A file's text (its bytes, if it is not UTF-8), from offset_bytes. A file that is not UTF-8 is
	// answered to an MCP tool by its size alone: CreateLink download_path fetches it, RunCommand
	// (`file`, `xxd`) looks inside.
	ReadFile(context.Context, *sandboxesv1.ReadFileRequest) (*sandboxesv1.File, error)
	// A directory's entries, `depth` levels deep, 1000 a page. A file's path lists that file alone.
	ListFiles(context.Context, *sandboxesv1.ListFilesRequest) (*sandboxesv1.ListFilesResponse, error)
	// Changes files in order (writes, edits, moves, deletes, directories), and stops at the first
	// that fails. A write replaces the file whole, keeping its owner and mode: a hard link to it
	// keeps the old content; a symbolic link is written through to its target.
	WriteFiles(context.Context, *sandboxesv1.WriteFilesRequest) (*sandboxesv1.WriteFilesResponse, error)
	// Changes under a directory, live, until the stream is closed.
	WatchFiles(context.Context, *sandboxesv1.WatchFilesRequest) (SandboxRuntimeServiceWatchFilesClientStream, error)
	// Does the actions in order, then answers with a screenshot of the screen as they left it, and
	// where the pointer is. Stops at the first that fails; with no actions, just the screenshot.
	// The first starts the desktop, which takes some seconds. FAILED_PRECONDITION = the desktop did
	// not start, or the sandbox has not started since its server took the release of a field the
	// request holds: stop it and start it again (its words say which). A program that drives the
	// browser by its pages rather than by the screen takes CreateLink browser.
	ControlDesktop(context.Context, *sandboxesv1.ControlDesktopRequest) (*sandboxesv1.ControlDesktopResponse, error)
	// A URL, for a browser or curl, into one thing of the sandbox: a terminal, the screen, a file
	// to download or upload, or the browser for Playwright or Puppeteer (BrowserLink); or a private
	// port's address and a token for it. It expires. A download or upload link works once. Making
	// one wakes nothing.
	//
	// A private port answers only a request that sends its token as the header `Pethost-Token:
	// <token>`: a program's, curl's, a page's fetch. The server checks it before anything wakes and
	// takes the header off; the rest reaches the program as it was sent, Authorization and Cookie
	// included. A preflight that names the header is answered 204 by the server itself, and the
	// answer to a request whose token it took carries Access-Control-Allow-Origin with the request's
	// origin, without credentials, so that a page of any origin may call the port with a token it
	// holds. A browser's tab, a WebSocket or an image sends no such header: what a browser opens is a
	// public port (Ingress), or a port forwarded by `ssh -L`. Every sandbox's address is under one
	// domain: the server takes the Domain off a cookie an answer sets, and an app keeps the cookies
	// its pages set to its own address with the `__Host-` prefix.
	CreateLink(context.Context, *sandboxesv1.CreateLinkRequest) (*sandboxesv1.Link, error)
	// Gives a coding agent a prompt, in a new conversation or conversation_id's, and waits for its
	// turn (wait_seconds). A conversation runs one turn at a time: a prompt to a busy one is
	// QUEUED. When a turn ends, the agent and its helpers end with it; what its commands left
	// running in the background (a dev server, say) runs on unless the agent ends it itself.
	// FAILED_PRECONDITION + AgentSignIn = the agent cannot reach its model.
	PromptAgent(context.Context, *sandboxesv1.PromptAgentRequest) (*sandboxesv1.AgentTurn, error)
	// A turn, after waiting for it to end (wait_seconds).
	GetAgentTurn(context.Context, *sandboxesv1.GetAgentTurnRequest) (*sandboxesv1.AgentTurn, error)
	// Ends a turn now, or takes a QUEUED one off the queue. What it changed stays changed.
	StopAgentTurn(context.Context, *sandboxesv1.StopAgentTurnRequest) (*sandboxesv1.AgentTurn, error)
	// The sandbox's conversations, newest first, 50 a page.
	ListConversations(context.Context, *sandboxesv1.ListConversationsRequest) (*sandboxesv1.ListConversationsResponse, error)
	// A conversation's events after after_seq, then live: prompts, messages, tool calls with their
	// input and output, and the end of each turn.
	WatchConversation(context.Context, *sandboxesv1.WatchConversationRequest) (SandboxRuntimeServiceWatchConversationClientStream, error)
}

